const __pageData = JSON.parse('{"title":"Volodymyr Zelensky","description":"","frontmatter":{"title":"Volodymyr Zelensky","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["ukraine","war","conscription","nato"],"sources":["raw/a-bright-red-line.md","raw/badlands-brief-07c.md","raw/badlands-brief-094.md","raw/badlands-brief-245.md","raw/badlands-brief-3d4.md","raw/badlands-brief-618.md","raw/badlands-brief-6f4.md","raw/badlands-brief-70c.md","raw/badlands-brief-805.md","raw/badlands-brief-be1.md","raw/badlands-brief-e9a.md","raw/badlands-brief-fbb.md","raw/badlands-brief.md","raw/badlands-news-brief-017.md","raw/badlands-news-brief-020.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-065.md","raw/badlands-news-brief-079.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-0c1.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-1ab.md","raw/badlands-news-brief-1e2.md","raw/badlands-news-brief-254.md","raw/badlands-news-brief-25f.md","raw/badlands-news-brief-299.md","raw/badlands-news-brief-290.md","raw/badlands-news-brief-2ad.md","raw/badlands-news-brief-2ca.md","raw/badlands-news-brief-2dc.md","raw/badlands-news-brief-324.md","raw/badlands-news-brief-356.md","raw/badlands-news-brief-397.md","raw/badlands-news-brief-3a5.md","raw/badlands-news-brief-3f0.md","raw/badlands-news-brief-3c3.md","raw/badlands-news-brief-3d2.md","raw/badlands-news-brief-421.md","raw/badlands-news-brief-42e.md","raw/badlands-news-brief-457.md","raw/badlands-news-brief-467.md","raw/badlands-news-brief-4a6.md","raw/badlands-news-brief-4a9.md","raw/badlands-news-brief-505.md","raw/badlands-news-brief-50f.md","raw/badlands-news-brief-528.md","raw/badlands-news-brief-508.md","raw/badlands-news-brief-536.md","raw/badlands-news-brief-525.md","raw/badlands-news-brief-58e.md","raw/badlands-news-brief-576.md","raw/badlands-news-brief-575.md","raw/badlands-news-brief-601.md","raw/badlands-news-brief-6aa.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-6f7.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-670.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-74c.md","raw/badlands-news-brief-763.md","raw/badlands-news-brief-7b1.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-817.md","raw/badlands-news-brief-824.md","raw/badlands-news-brief-8ba.md","raw/badlands-news-brief-8f0.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/volodymyr-zelensky.md","filePath":"entities/volodymyr-zelensky.md","lastUpdated":null}');
